import assert from 'node:assert/strict';
import {backup} from 'node:sqlite';
import {createHash} from 'node:crypto';
import {mkdtempSync,mkdirSync,readFileSync,writeFileSync,statSync,rmSync,existsSync} from 'node:fs';
import {join,dirname} from 'node:path';
import {createTestD1} from './helpers/d1.mjs';
import {PlanRepository} from '../lib/plan-repository.ts';
import {accountPersonId} from '../lib/people.ts';
import {exportBackupBundle,rehearseBackupRestore,retainBackupBundles} from '../scripts/support/backup-bundle.mjs';
import {verifyBackup} from '../scripts/support/backup-verification.mjs';
const sha=value=>createHash('sha256').update(value).digest('hex'),png=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVQIHWP4z8DwHwAFgAI/ScLbtAAAAABJRU5ErkJggg==','base64');let checks=0;
async function check(name,run){mkdirSync(join(process.cwd(),'build'),{recursive:true});const database=createTestD1(),directory=mkdtempSync(join(process.cwd(),'build','backup-bundle-'));try{const owner='bundle-owner',identity={id:await accountPersonId(owner),name:'Fixture'},repository=new PlanRepository(database),record=await repository.createPlan(owner,identity,{name:'Bundle fixture',destination:'Toronto',start:'2027-04-04',end:'2027-04-04',timezone:'America/Toronto',currency:'CAD',budget:1000});
 const objectsDirectory=join(directory,'objects');mkdirSync(objectsDirectory);const keys=[sha(owner)+'/12345678-1234-4234-8234-123456789abc',sha(owner)+'/documents/12345678-1234-4234-8234-123456789abd'];for(const key of keys){const file=join(objectsDirectory,...key.split('/'));mkdirSync(dirname(file),{recursive:true});writeFileSync(file,png);}await database.prepare("INSERT INTO receipt_objects(file_key,owner,plan_id,status,created) VALUES (?,?,?,'ready','2027-04-04T00:00:00Z')").bind(keys[0],owner,record.state.plan.id).run();
 await database.prepare("INSERT INTO document_objects(file_key,owner,plan_id,status,created,source_sha256,size,mime) VALUES (?,?,?,'ready','2027-04-04T00:00:00Z',?,?,'image/png')").bind(keys[1],owner,record.state.plan.id,sha(png),png.length).run();
 await database.prepare('INSERT INTO trip_documents(id,owner,trip_id,uploader,body,file_key,version,size,source_sha256) VALUES (?,?,?,?,?,?,1,?,?)').bind('document-fixture',owner,record.state.plan.id,identity.id,JSON.stringify({mimeType:'image/png',filename:'private-file-name.png'}),keys[1],png.length,sha(png)).run();
 const databasePath=join(directory,'source.sqlite');await backup(database.sqlite,databasePath);await run({database,directory,keys,options:{databasePath,objectsDirectory,outputDirectory:join(directory,'bundle')}});checks++;console.log('PASS '+name);
 }finally{database.close();rmSync(directory,{recursive:true,force:true});}}
await check('Complete bundle captures DB plus receipt/document bytes and independent hashes without source modification',async t=>{const bytes=readFileSync(t.options.databasePath),mtime=statSync(t.options.databasePath).mtimeMs,manifest=join(t.directory,'independent.json');const result=await exportBackupBundle({...t.options,independentManifestPath:manifest});assert.equal(result.status,'complete');assert.equal(result.objects,2);assert.equal(result.hostedRestoreVerified,false);assert.deepEqual(readFileSync(t.options.databasePath),bytes);assert.equal(statSync(t.options.databasePath).mtimeMs,mtime);assert.deepEqual(readFileSync(manifest),readFileSync(join(t.options.outputDirectory,'manifest.json')));assert.equal(verifyBackup({databasePath:join(t.options.outputDirectory,'database.sqlite'),objectsDirectory:join(t.options.outputDirectory,'objects'),manifestPath:manifest,requireManifest:true}).ok,true);});
await check('A bounded partial capture resumes exactly and refuses changed source bytes',async t=>{let result=await exportBackupBundle({...t.options,batchSize:1});assert.equal(result.status,'incomplete');assert.equal(result.captured,1);assert.equal(existsSync(join(t.options.outputDirectory,'BACKUP_COMPLETE.json')),false);result=await exportBackupBundle({...t.options,resume:true,batchSize:1});assert.equal(result.status,'complete');await assert.rejects(()=>exportBackupBundle({...t.options,resume:true}),/completed bundle/i);});
await check('Same-size source document substitution fails its retained digest and failed exports stay incomplete',async t=>{const file=join(t.options.objectsDirectory,...t.keys[1].split('/')),changed=Buffer.from(png);changed[changed.length-1]^=1;writeFileSync(file,changed);await assert.rejects(()=>exportBackupBundle(t.options),/digest/i);assert.equal(existsSync(join(t.options.outputDirectory,'BACKUP_COMPLETE.json')),false);});
await check('Source sidecars and unsafe nesting fail before copying; explicit output never overwrites',async t=>{writeFileSync(t.options.databasePath+'-wal','fixture');await assert.rejects(()=>exportBackupBundle(t.options),/sidecars/i);rmSync(t.options.databasePath+'-wal');await assert.rejects(()=>exportBackupBundle({...t.options,outputDirectory:join(t.options.objectsDirectory,'unsafe')}),/separate/i);mkdirSync(t.options.outputDirectory);await assert.rejects(()=>exportBackupBundle(t.options),/exists/i);});
await check('Isolated restore rehearsal verifies a separate copy and never activates a runtime',async t=>{await exportBackupBundle(t.options);const result=await rehearseBackupRestore({bundleDirectory:t.options.outputDirectory,outputDirectory:join(t.directory,'rehearsal')});assert.equal(result.ok,true);assert.equal(result.networkUsed,false);assert.equal(result.runtimeActivated,false);assert.equal(result.hostedRestoreVerified,false);assert.ok(existsSync(join(t.directory,'rehearsal','REHEARSAL_ONLY.json')));});
await check('Retention defaults to dry-run and deletes only marked verified complete bundles within the explicit root',async t=>{const root=join(t.directory,'retention');mkdirSync(root);for(const name of ['one','two','three'])await exportBackupBundle({...t.options,outputDirectory:join(root,name)});mkdirSync(join(root,'unmarked'));writeFileSync(join(root,'unmarked','keep.txt'),'keep');let report=retainBackupBundles({directory:root,keep:1});assert.equal(report.candidates,2);assert.equal(report.removed,0);assert.equal(existsSync(join(root,'one')),true);report=retainBackupBundles({directory:root,keep:1,apply:true});assert.equal(report.removed,2);assert.equal(existsSync(join(root,'unmarked','keep.txt')),true);});
console.log(`${checks} complete offline backup capture/retention/rehearsal checks passed; no hosted export or provider calls.`);
